# Task: Download all parks in Pennsylvania from OpenStreetMap and save to C:/Users/akinb/Documents/parks.shp
# Approach:
# - Use OSMnx to geocode Pennsylvania and obtain its OSM relation id (fast and robust).
# - Use Overpass API to fetch features tagged as parks within the Pennsylvania boundary:
#     * leisure=park
#     * boundary=national_park
#   Query both ways and relations and request geometries (out geom).
# - Parse ways (closed rings) and relations (multipolygons with outer/inner members) into Shapely geometries.
# - Preserve most attributes (tags + osm ids and types).
# - Save as ESRI Shapefile in EPSG:4326 to the specified output path.
#
# Notes:
# - We follow the handbook pipeline strictly: relation(osm_id); map_to_area->.rel; ... out geom;
# - Shapefile field names may be truncated to 10 chars by the driver; attributes are preserved best-effort.
# - If no data are retrieved, the function raises an error.

import os
import json
import requests
import pandas as pd
import geopandas as gpd
import osmnx as ox
from shapely.geometry import Polygon, MultiPolygon, LineString
from shapely.ops import linemerge, unary_union, polygonize

def _polygon_from_way_geometry(pts):
    # pts: list of dicts [{'lat':..., 'lon':...}, ...]
    coords = [(p['lon'], p['lat']) for p in pts if ('lon' in p and 'lat' in p)]
    if len(coords) < 4:
        return None
    if coords[0] != coords[-1]:
        coords = coords + [coords[0]]
    try:
        poly = Polygon(coords)
        if not poly.is_valid:
            poly = poly.buffer(0)
        return poly if not poly.is_empty else None
    except Exception:
        return None

def _polygon_from_relation_members(members):
    # Build polygons from relation members using roles outer/inner
    outer_lines = []
    inner_lines = []
    for m in members:
        if m.get('type') == 'way' and 'geometry' in m and isinstance(m['geometry'], list):
            way_pts = [(pt['lon'], pt['lat']) for pt in m['geometry'] if ('lon' in pt and 'lat' in pt)]
            if len(way_pts) >= 2:
                try:
                    ls = LineString(way_pts)
                    if m.get('role') == 'inner':
                        inner_lines.append(ls)
                    else:
                        # default to outer if role unspecified or 'outer'
                        outer_lines.append(ls)
                except Exception:
                    continue

    if not outer_lines:
        return None

    def lines_to_multipolygon(lines):
        merged = linemerge(lines)
        borders = unary_union(merged)
        polys = list(polygonize(borders))
        if len(polys) == 0:
            return None
        if len(polys) == 1:
            return polys[0]
        return MultiPolygon(polys)

    outer_mp = lines_to_multipolygon(outer_lines)
    if outer_mp is None:
        return None

    if inner_lines:
        inner_mp = lines_to_multipolygon(inner_lines)
        if inner_mp is not None:
            try:
                result = outer_mp.difference(inner_mp)
                if result.is_empty:
                    return outer_mp
                return result
            except Exception:
                return outer_mp
    return outer_mp

def download_data():
    place_name = "Pennsylvania, USA"
    output_shp = r"C:/Users/akinb/Documents/parks.shp"

    # 1) Get OSM relation id for the state boundary via OSMnx (fast and robust)
    boundary_gdf = ox.geocode_to_gdf(place_name)
    osm_id = int(boundary_gdf['osm_id'].iloc[0])

    # 2) Build Overpass query for parks within the area
    overpass_url = "https://overpass-api.de/api/interpreter"
    overpass_query = f"""
    [out:json][timeout:180];
    relation({osm_id});
    map_to_area->.rel;
    (
      way(area.rel)["leisure"="park"];
      relation(area.rel)["leisure"="park"];
      way(area.rel)["boundary"="national_park"];
      relation(area.rel)["boundary"="national_park"];
    );
    out body geom;
    """

    # 3) Fetch data
    response = requests.get(overpass_url, params={'data': overpass_query})
    response.raise_for_status()
    data = response.json()

    if 'elements' not in data or len(data['elements']) == 0:
        raise ValueError("No park features were returned by Overpass for Pennsylvania.")

    # 4) Parse elements into geometries and attributes
    geoms = []
    props = []

    for el in data['elements']:
        el_type = el.get('type')
        el_id = el.get('id')
        tags = el.get('tags', {}) or {}

        geom = None
        if el_type == 'way':
            if 'geometry' in el:
                geom = _polygon_from_way_geometry(el['geometry'])
        elif el_type == 'relation':
            members = el.get('members', [])
            geom = _polygon_from_relation_members(members)

        # Some parks are mapped as closed-way polygons; ignore elements that failed to build geometry
        if geom is None or geom.is_empty:
            continue

        # Flatten properties: include OSM id/type and all tags
        prop = {'osm_id': el_id, '_osm_type': el_type}
        for k, v in tags.items():
            # normalize to string for shapefile safety
            try:
                prop[k] = ', '.join(map(str, v)) if isinstance(v, list) else str(v)
            except Exception:
                prop[k] = str(v)
        props.append(prop)
        geoms.append(geom)

    if len(geoms) == 0:
        raise ValueError("No valid park geometries could be constructed from Overpass response.")

    gdf = gpd.GeoDataFrame(pd.DataFrame(props), geometry=geoms, crs="EPSG:4326")

    # 5) Ensure output directory exists
    os.makedirs(os.path.dirname(output_shp), exist_ok=True)

    # 6) Save to Shapefile
    gdf.to_file(output_shp, driver="ESRI Shapefile")

download_data()
